        function parseCSV(text) {
            var rows = [], row = [], cur = "", q = false;
            for(var i = 0; i < text.length; i++){
                var c = text[i];
                if (q) {
                    if (c === '"') {
                        if (text[i + 1] === '"') {
                            cur += '"';
                            i++;
                        } else q = false;
                    } else cur += c;
                } else if (c === '"') q = true;
                else if (c === ",") {
                    row.push(cur);
                    cur = "";
                } else if (c === "\n" || c === "\r") {
                    if (c === "\r" && text[i + 1] === "\n") i++;
                    row.push(cur);
                    rows.push(row);
                    row = [];
                    cur = "";
                } else cur += c;
            }
            if (cur || row.length) {
                row.push(cur);
                rows.push(row);
            }
            return rows.map(function(r) {
                return r.map(function(x) {
                    return x.trim();
                });
            }).filter(function(r) {
                return r.some(Boolean);
            });
        }
